import{describe,it,expect,beforeAll}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function loadVembanadLakeData(){const e=readFileSync(resolve(__dirname,"../../frontend/vembanad-lake-explorer/vembanad-lake-data.js"),"utf-8");return new Function(e+"\nreturn { VEMBANAD_LAKE_INFO, ECOLOGY_HYDROLOGY, WILDLIFE_SPECIES, MAP_HOTSPOTS, GALLERY_IMAGES };")()}function loadWetlandsLandingData(){let e=readFileSync(resolve(__dirname,"../../frontend/wetlands/wetlands-data.js"),"utf-8");e=e.replace(/export\s+const\s+/g,"const ");return new Function(e+"\nreturn WETLANDS_DATA;")()}describe("Vembanad Lake Explorer — Data & Integration Tests",()=>{let e;beforeAll(()=>{e=loadVembanadLakeData()}),describe("VEMBANAD_LAKE_INFO metadata",()=>{it("contains correct wetland metadata and status",()=>{expect(e.VEMBANAD_LAKE_INFO.id).toBe("vembanad-lake-explorer"),expect(e.VEMBANAD_LAKE_INFO.name).toContain("Vembanad"),expect(e.VEMBANAD_LAKE_INFO.ramsarYear).toBe(2002),expect(e.VEMBANAD_LAKE_INFO.ramsarSiteNo).toBe(1215),expect(e.VEMBANAD_LAKE_INFO.state).toBe("Kerala")}),it("has quickStats array with 6 items",()=>{expect(Array.isArray(e.VEMBANAD_LAKE_INFO.quickStats)).toBe(!0),expect(e.VEMBANAD_LAKE_INFO.quickStats.length).toBe(6)})}),describe("ECOLOGY_HYDROLOGY",()=>{it("contains geography, ramsarSite, kumarakomSanctuary, backwaterTourism, houseboats, mangroves, fisheries, and interestingFacts",()=>{expect(e.ECOLOGY_HYDROLOGY.geography).toBeDefined(),expect(e.ECOLOGY_HYDROLOGY.ramsarSite).toBeDefined(),expect(e.ECOLOGY_HYDROLOGY.kumarakomSanctuary).toBeDefined(),expect(e.ECOLOGY_HYDROLOGY.backwaterTourism).toBeDefined(),expect(e.ECOLOGY_HYDROLOGY.houseboats).toBeDefined(),expect(e.ECOLOGY_HYDROLOGY.mangroves).toBeDefined(),expect(e.ECOLOGY_HYDROLOGY.fisheries).toBeDefined(),expect(Array.isArray(e.ECOLOGY_HYDROLOGY.interestingFacts)).toBe(!0),expect(e.ECOLOGY_HYDROLOGY.interestingFacts.length).toBeGreaterThanOrEqual(4)})}),describe("WILDLIFE_SPECIES catalog",()=>{it("is a non-empty array of species",()=>{expect(Array.isArray(e.WILDLIFE_SPECIES)).toBe(!0),expect(e.WILDLIFE_SPECIES.length).toBeGreaterThanOrEqual(4)}),it("includes Pearl Spot (Karimeen)",()=>{const t=e.WILDLIFE_SPECIES.find(e=>"pearl-spot"===e.id);expect(t).toBeDefined()})}),describe("Landing Page Integration",()=>{it("is integrated in WETLANDS_DATA landing page dataset",()=>{const e=loadWetlandsLandingData().wetlands.find(e=>"vembanad-lake"===e.id);expect(e).toBeDefined(),expect(e.exploreUrl).toBe("../vembanad-lake-explorer/index.html")})})});